uct->id): echo 'selected'; endif; ?>><?php echo e($product->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><?php endif; ?>@if($report==='stock')<div class="col-md-3"><label class="form-label">Warehouse</label><select class="form-select" name="warehouse_id"><option value="">All warehouses</option><?php $__currentLoopData = $warehouses; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $warehouse): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($warehouse->id); ?>" <?php if(($filters['warehouse_id']??null)==$warehouse->id): echo 'selected'; endif; ?>><?php echo e($warehouse->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><?php endif; ?>@if(in_array($report,['sales','customer-ledger']))<div class="col-md-3"><label class="form-label">Customer</label><select class="form-select" name="customer_id"><option value="">All customers</option><?php if($report==='sales'): ?><option value="walking" <?php if(($filters['customer_id']??null)==='walking'): echo 'selected'; endif; ?>>Walking customer / guest</option><?php endif; ?> <?php $__currentLoopData = $customers; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $customer): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($customer->id); ?>" <?php if(($filters['customer_id']??null)==$customer->id): echo 'selected'; endif; ?>><?php echo e($customer->full_name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><?php endif; ?>@if(in_array($report,['purchase','supplier-ledger']))<div class="col-md-3"><label class="form-label">Supplier</label><select class="form-select" name="supplier_id"><option value="">All suppliers</option><?php $__currentLoopData = $suppliers; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $supplier): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($supplier->id); ?>" <?php if(($filters['supplier_id']??null)==$supplier->id): echo 'selected'; endif; ?>><?php echo e($supplier->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><?php endif; ?><div class="col-md-2 d-flex align-items-end"><button class="btn text-white w-100" style="background:var(--brand)">Apply filter</button></div></form></div>
<div class="row g-3 mb-4"><?php $__currentLoopData = $summary; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $label=>$value): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><div class="col-md-3"><div class="panel py-3"><small class="text-muted text-uppercase"><?php echo e($label); ?></small><div class="fs-4 fw-bold"><?php echo e($label === 'quantity' ? number_format($value,3) : (is_numeric($value) ? '$'.number_format($value,2) : $value)); ?></div></div></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div><div class="panel p-0 overflow-hidden"><div class="table-responsive"><table class="table mb-0"><thead><tr><?php if($report==='stock'): ?><th>Warehouse</th><th>Product</th><th>Available quantity</th><th>Last updated</th><?php elseif($report==='sales'): ?><th>Order</th><th>Date</th><th>Customer</th><th>Items</th><th>Total</th><?php elseif($report==='purchase'): ?><th>Purchase</th><th>Date</th><th>Supplier</th><th>Warehouse</th><th>Total</th><?php else: ?><th>Date</th><th>Voucher</th><th>Account</th><th>Note</th><th>Debit</th><th>Credit</th><?php endif; ?></tr></thead><tbody><?php $__empty_1 = true; $__currentLoopData = $rows; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $row): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr><?php if($report==='stock'): ?><td><?php echo e($row->warehouse->name); ?></td><td><?php echo e($row->product->name); ?></td><td><?php echo e(number_format($row->quantity,3)); ?></td><td><?php echo e($row->updated_at->format('d M Y H:i')); ?></td><?php elseif($report==='sales'): ?><td><?php echo e($row->order_number); ?></td><td><?php echo e($row->created_at->format('d M Y')); ?></td><td><?php echo e($row->customer?->full_name ?: 'Walking customer / guest'); ?></td><td><?php echo e($row->items->sum('quantity')); ?></td><td>$<?php echo e(number_format($row->total,2)); ?></td><?php elseif($report==='purchase'): ?><td><?php echo e($row->purchase_number); ?></td><td><?php echo e($row->purchase_date->format('d M Y')); ?></td><td><?php echo e($row->supplier?->name ?: $row->supplier_name); ?></td><td><?php echo e($row->warehouse->name); ?></td><td>$<?php echo e(number_format($row->total,2)); ?></td><?php else: ?><td><?php echo e($row->transaction_date->format('d M Y')); ?></td><td><?php echo e($row->voucher_no); ?></td><td><?php echo e($row->account->code); ?> — <?php echo e($row->account->head_name); ?></td><td><?php echo e($row->ledger_comment); ?></td><td><?php echo e($row->entry_type==='debit' ? '$'.number_format($row->amount,2) : '—'); ?></td><td><?php echo e($row->entry_type==='credit' ? '$'.number_format($row->amount,2) : '—'); ?></td><?php endif; ?></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="6" class="text-center py-5 text-muted">No matching data found.</td></tr><?php endif; ?></tbody></table></div></div><div class="mt-3"><?php echo e($rows->withQueryString()->links()); ?></div>
